import json
d = json.load(open('input/pr-1350/pr_discussions_raw.json'))
print('top keys:', list(d.keys()))
for t in d.get('threads', []):
    print('thread', t['index'], 'path:', t['path'], 'line:', t['line'], 'resolved:', t['resolved'], 'keys:', list(t.keys()))
    for k in ('replies','comments'):
        if k in t:
            for c in t[k]:
                print('  ', k, '|', c.get('author',{}).get('login','?'), '|', c.get('createdAt',''), '|', (c.get('body','') or '')[:200].replace(chr(10),' / '))
gen = d.get('generalComments') or d.get('general') or []
for c in gen:
    print('general |', c.get('author',{}).get('login','?'), '|', c.get('createdAt',''))
""}

