  '.github/workflows/nightly.yml',
  '.github/workflows/build-mobile.yml',
  '.github/workflows/build-macos.yml',
  '.github/workflows/browser-ext.yml',
  '.github/workflows/office-addin.yml',
  '.github/workflows/pages.yml',
];

